import{_ as e,o,c as r,a2 as i}from"./chunks/framework.CgxQ0r6v.js";const m=JSON.parse('{"title":"Manual de Estudio Profundo: Evaluación 3","description":"","frontmatter":{},"headers":[],"relativePath":"materias/Redes/documentacion/II-IV/Lectura_Catedra_Evaluacion_3.md","filePath":"materias/Redes/documentacion/II-IV/Lectura_Catedra_Evaluacion_3.md"}'),n={name:"materias/Redes/documentacion/II-IV/Lectura_Catedra_Evaluacion_3.md"};function s(t,a,l,c,d,u){return o(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="manual-de-estudio-profundo-evaluacion-3" tabindex="-1">Manual de Estudio Profundo: Evaluación 3 <a class="header-anchor" href="#manual-de-estudio-profundo-evaluacion-3" aria-label="Permalink to &quot;Manual de Estudio Profundo: Evaluación 3&quot;">​</a></h1><h2 id="materia-redes-trayecto-ii" tabindex="-1">Materia: Redes (Trayecto II) <a class="header-anchor" href="#materia-redes-trayecto-ii" aria-label="Permalink to &quot;Materia: Redes (Trayecto II)&quot;">​</a></h2><h3 id="eje-tematico-protocolos-y-modelos-de-comunicacion-osi-y-tcp-ip" tabindex="-1">Eje Temático: Protocolos y Modelos de Comunicación (OSI y TCP/IP) <a class="header-anchor" href="#eje-tematico-protocolos-y-modelos-de-comunicacion-osi-y-tcp-ip" aria-label="Permalink to &quot;Eje Temático: Protocolos y Modelos de Comunicación (OSI y TCP/IP)&quot;">​</a></h3><hr><h2 id="🧭-introduccion-la-torre-de-babel-tecnologica" tabindex="-1">🧭 Introducción: La Torre de Babel Tecnológica <a class="header-anchor" href="#🧭-introduccion-la-torre-de-babel-tecnologica" aria-label="Permalink to &quot;🧭 Introducción: La Torre de Babel Tecnológica&quot;">​</a></h2><p>En la década de 1970 y principios de los 80, el mundo de las computadoras era un caos. Si tu empresa compraba computadoras a IBM, formaban su propia red. Si luego compraban computadoras a Apple o a Digital Equipment Corporation (DEC), estas no podían conectarse a la red de IBM. Cada fabricante inventaba su propio cable, su propio voltaje y su propio idioma.</p><p>Para evitar que el mundo tecnológico se fragmentara en tribus aisladas, la <strong>ISO (Organización Internacional de Normalización)</strong> decidió crear un estándar universal de paz. Un &quot;Esperanto&quot; computacional. Si todos los fabricantes del mundo fabricaban sus tarjetas y sistemas operativos siguiendo ese mismo estándar de múltiples capas, un computador Mac en Japón podría hablar con un servidor IBM en Caracas sin problemas. Así nació el <strong>Modelo OSI (Open Systems Interconnection)</strong>.</p><hr><h2 id="🏛️-capitulo-i-el-modelo-osi-anatomia-en-7-capas" tabindex="-1">🏛️ CAPÍTULO I: El Modelo OSI (Anatomía en 7 Capas) <a class="header-anchor" href="#🏛️-capitulo-i-el-modelo-osi-anatomia-en-7-capas" aria-label="Permalink to &quot;🏛️ CAPÍTULO I: El Modelo OSI (Anatomía en 7 Capas)&quot;">​</a></h2><p>El Modelo OSI dividió la colosal tarea de transmitir datos por la red en <strong>7 Capas independientes</strong>. La genialidad de esta arquitectura es la &quot;Abstracción&quot;. A la Capa 7 (tu navegador web) no le importa si estás conectado por cable de cobre o por Wi-Fi (Capa 1). Cada capa hace su trabajo y se lo pasa a la capa de abajo.</p><p><em>(Regla mnemotécnica para recordarlas de abajo hacia arriba: FERTSPA - Física, Enlace, Red, Transporte, Sesión, Presentación, Aplicación).</em></p><h3 id="las-capas-de-hardware-medio-fisico" tabindex="-1">Las Capas de Hardware (Medio Físico) <a class="header-anchor" href="#las-capas-de-hardware-medio-fisico" aria-label="Permalink to &quot;Las Capas de Hardware (Medio Físico)&quot;">​</a></h3><ul><li><strong>1. Capa Física:</strong> Lidiar con lo tangible. Cables de cobre, luz óptica, radiofrecuencia y conectores RJ45. Solo maneja <strong>Bits</strong> puros (101010).</li><li><strong>2. Capa de Enlace de Datos:</strong> Organiza los bits en agrupaciones lógicas llamadas <strong>Tramas (Frames)</strong>. Aquí trabaja el Switch. Utiliza las <strong>Direcciones MAC</strong> físicas para entregar los datos a la computadora correcta dentro de un mismo edificio (LAN).</li><li><strong>3. Capa de Red:</strong> Aquí trabaja el Router. Utiliza las <strong>Direcciones IP</strong> (Lógicas). Su trabajo es trazar el mapa de GPS, calcular la mejor ruta por internet y enviar el <strong>Paquete (Packet)</strong> cruzando países enteros hacia otra red lejana.</li></ul><h3 id="la-capa-intermedia-corazon" tabindex="-1">La Capa Intermedia (Corazón) <a class="header-anchor" href="#la-capa-intermedia-corazon" aria-label="Permalink to &quot;La Capa Intermedia (Corazón)&quot;">​</a></h3><ul><li><strong>4. Capa de Transporte:</strong> Se asegura de que el mensaje llegue completo y en orden. Maneja <strong>Segmentos</strong>. Sus dos protocolos estrella son TCP (Lento pero 100% seguro de que el archivo no está corrupto) y UDP (Hiper-rápido pero sin garantías, usado en llamadas por Zoom o Videojuegos online).</li></ul><h3 id="las-capas-de-software-usuario-final" tabindex="-1">Las Capas de Software (Usuario final) <a class="header-anchor" href="#las-capas-de-software-usuario-final" aria-label="Permalink to &quot;Las Capas de Software (Usuario final)&quot;">​</a></h3><ul><li><strong>5. Capa de Sesión:</strong> Mantiene abierta la &quot;llamada telefónica&quot; (sesión lógica) entre las dos computadoras mientras transfieren archivos.</li><li><strong>6. Capa de Presentación:</strong> El traductor del sistema operativo. Comprime los datos, los encripta (SSL) o transforma caracteres ASCII.</li><li><strong>7. Capa de Aplicación:</strong> El software que el usuario ve. Tu navegador Chrome (usando el protocolo HTTP), o tu cliente de correo Outlook (SMTP, POP3).</li></ul><hr><h2 id="🧩-capitulo-ii-el-concepto-de-encapsulamiento-la-matryoshka-rusa" tabindex="-1">🧩 CAPÍTULO II: El Concepto de Encapsulamiento (La Matryoshka Rusa) <a class="header-anchor" href="#🧩-capitulo-ii-el-concepto-de-encapsulamiento-la-matryoshka-rusa" aria-label="Permalink to &quot;🧩 CAPÍTULO II: El Concepto de Encapsulamiento (La Matryoshka Rusa)&quot;">​</a></h2><p>Cuando tú escribes un correo y le das a &quot;Enviar&quot;, ese texto puro de la Capa 7 comienza a bajar hacia la Capa 1. En cada capa por la que pasa, se le añade un <strong>Encabezado (Header)</strong> con instrucciones para el cartero.</p><ol><li>Escribes el correo (Datos - C. Aplicación).</li><li>La C. Transporte agarra el correo, lo mete en un sobre y le pone la etiqueta &quot;Protocolo TCP, asegurar entrega&quot; (Ahora es un Segmento).</li><li>La C. Red agarra ese sobre, lo mete en un sobre más grande y le pone la &quot;IP Origen y la IP Destino&quot; (Ahora es un Paquete).</li><li>La C. Enlace agarra ese paquete, lo mete en una caja dura y le pone &quot;MAC de mi Tarjeta y MAC de mi Router&quot; (Ahora es una Trama).</li><li>La caja dura se tritura temporalmente en millones de chispazos de electricidad 1 y 0 (Bits), viaja por el cable submarino y llega al servidor de Google.</li><li>El Servidor de Google hace el proceso inverso (<strong>Desencapsulamiento</strong>): Recibe los bits, arma la caja, rompe el sobre grande, rompe el sobre pequeño y finalmente lee el correo original.</li></ol><hr><h2 id="🏗️-capitulo-iii-osi-vs-tcp-ip-la-teoria-vs-la-realidad" tabindex="-1">🏗️ CAPÍTULO III: OSI vs TCP/IP (La Teoría vs La Realidad) <a class="header-anchor" href="#🏗️-capitulo-iii-osi-vs-tcp-ip-la-teoria-vs-la-realidad" aria-label="Permalink to &quot;🏗️ CAPÍTULO III: OSI vs TCP/IP (La Teoría vs La Realidad)&quot;">​</a></h2><p>El Modelo OSI es el mejor modelo del mundo para enseñar redes en las universidades (Es el estándar académico). Sin embargo, el gobierno de los Estados Unidos (específicamente DARPA) creó su propio sistema paralelo de redes en los años 70: <strong>El Modelo TCP/IP</strong>.</p><p>TCP/IP fue el sistema que realmente se instaló en las computadoras e impulsó el Internet moderno, porque era más práctico. Mientras OSI tiene 7 capas teóricas perfectas, TCP/IP colapsó algunas de esas capas en solo 4 capas prácticas:</p><ol><li><strong>Capa de Acceso a la Red</strong> (Equivale a Física + Enlace del OSI).</li><li><strong>Capa de Internet</strong> (Equivale a la Red del OSI. Aquí manda el Protocolo IP).</li><li><strong>Capa de Transporte</strong> (Igual que en OSI. Aquí mandan TCP y UDP).</li><li><strong>Capa de Aplicación</strong> (Fusiona Sesión, Presentación y Aplicación del OSI).</li></ol><p>Como ingeniero, debes conocer OSI para diagnosticar problemas teóricamente (&quot;Tengo un error de Capa 1&quot; = el cable está roto), pero debes saber que en las trincheras reales estarás configurando protocolos TCP/IP.</p><hr><h2 id="📘-anexo-diccionario-tecnico-formal" tabindex="-1">📘 ANEXO: Diccionario Técnico Formal <a class="header-anchor" href="#📘-anexo-diccionario-tecnico-formal" aria-label="Permalink to &quot;📘 ANEXO: Diccionario Técnico Formal&quot;">​</a></h2><ul><li><strong>Modelo OSI (Open Systems Interconnection):</strong> Marco de referencia conceptual normado por la ISO que particiona la complejidad de las telecomunicaciones en siete capas jerárquicas y modulares.</li><li><strong>Protocolo de Red:</strong> Conjunto riguroso de reglas sintácticas, semánticas y de sincronización que gobiernan y estandarizan el intercambio de información entre entidades comunicantes en un sistema distribuido.</li><li><strong>Encapsulamiento (Encapsulation):</strong> Proceso descendente en la pila de protocolos mediante el cual se le añaden sucesivas cabeceras de control (Headers) a la carga útil (Payload) a medida que atraviesa las diferentes capas arquitectónicas.</li><li><strong>Capa Física (L1):</strong> Nivel inferior del Modelo OSI responsable de la transmisión de bits puros, no estructurados, a través de los medios físicos de conducción.</li><li><strong>Dirección IP (Internet Protocol):</strong> Identificador numérico lógico y jerárquico asignado dinámicamente a una interfaz de red (Capa 3), utilizado para enrutar paquetes a través de fronteras geográficas y topológicas en arquitecturas WAN.</li><li><strong>TCP (Transmission Control Protocol):</strong> Protocolo fundamental de la Capa de Transporte (Capa 4), orientado a conexión, caracterizado por sus mecanismos de retransmisión, control de flujo y garantía incondicional de la integridad y secuenciación de los datos entregados.</li></ul>',30)])])}const g=e(n,[["render",s]]);export{m as __pageData,g as default};
